def place(job, nodes):
    eligible = []
    for node in nodes:
        if node['cordoned'] or node['zone'] != job['zone']:
            continue
        if node['free_cpu'] < job['cpu'] or node['free_mem_gib'] < job['mem_gib']:
            continue
        eligible.append((node['free_cpu'] - job['cpu'], node['name'], node))

    if not eligible:
        return None

    selected = min(eligible, key=lambda item: (item[0], item[1]))[2]
    selected['free_cpu'] -= job['cpu']
    selected['free_mem_gib'] -= job['mem_gib']
    selected['assigned_jobs'].append(job['id'])
    return selected['name']

job = {'id': 'batch-47', 'zone': 'west', 'cpu': 6, 'mem_gib': 16}
nodes = [
    {'name': 'node-a', 'zone': 'west', 'cordoned': False, 'free_cpu': 12, 'free_mem_gib': 24, 'assigned_jobs': []},
    {'name': 'node-b', 'zone': 'west', 'cordoned': False, 'free_cpu': 8, 'free_mem_gib': 32, 'assigned_jobs': []},
    {'name': 'node-c', 'zone': 'east', 'cordoned': False, 'free_cpu': 20, 'free_mem_gib': 64, 'assigned_jobs': []},
    {'name': 'node-d', 'zone': 'west', 'cordoned': True, 'free_cpu': 20, 'free_mem_gib': 64, 'assigned_jobs': []},
]
result = place(job, nodes)
